/* ===== Cancel-save offer — brand accent #d72585 (page CSS, must beat the bundled component stylesheet) ===== */

.cancel-save-offer-container {
  background: #ffffff !important;
  width: 100%;
  margin: auto;
  padding: 1em;
  box-sizing: border-box;
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: #121416;
}

.cancel-save-offer-headers-container {
  text-align: center;
  display: flex;
  width: 100%;
  justify-content: center;
  padding: 2.5em 1em 1.5em;
  margin: auto;
}

.cancel-save-offer-heading {
  font-size: 2.25em;
  font-weight: 600;
  color: #121416;
  line-height: 1.1;
  letter-spacing: -0.01em;
}

.cancel-save-offer-subheading {
  width: 100%;
  max-width: 32ch;
  margin: 0.5em auto 0;
  font-size: 1.0625em;
  line-height: 1.5;
  color: #69696e;
}

/* Center the card (overrides the bundled `margin: 1em` that was pushing it left) */
.cancel-save-offer-body-container {
  position: relative;
  display: flex !important;
  flex-direction: column;
  width: 100% !important;
  max-width: 560px !important;
  border: 1px solid #eaeaeb !important;
  color: #121416;
  border-radius: 12px !important;
  margin: 0.5em auto 1em !important;
  padding: 2.25em 2em 2em !important;
  box-sizing: border-box;
  background: #ffffff !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06) !important;
  overflow: hidden;
  text-align: center;
}

/* Badge: static, centered pill at the top of the card — no more overlap */
.cancel-save-offer-body-container .cancel-save-offer-offerLine {
  position: static !important;
  display: block !important;
  width: -moz-fit-content !important;
  width: fit-content !important;
  margin: 0 auto 1.25em !important;
  background: #d72585 !important;
  color: #ffffff !important;
  padding: 0.4em 0.9em !important;
  font-size: 0.75em !important;
  font-weight: 600 !important;
  letter-spacing: 0.03em !important;
  text-transform: uppercase !important;
  border-radius: 999px !important;
}

.image-features-container.top,
.image-features-container.bottom {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

.image-features-container.bottom { flex-direction: column-reverse; }

.image-features-container.right {
  display: flex;
  flex-direction: row-reverse;
  justify-content: center;
  align-items: center;
}

.image-features-container.left {
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: center;
}

.image { width: 100%; height: 100%; border-radius: 8px; }

/* Accent the headline price (overrides bundled navy) */
.subscription-features-container .discount-info {
  font-size: 1.5em !important;
  font-weight: 600 !important;
  margin-bottom: 0.5em !important;
  line-height: 1.2 !important;
  color: #d72585 !important;
}

.subscription-features-container .next-payment-cost {
  margin-bottom: 0.35em;
  color: #121416 !important;
  font-size: 1.0625em !important;
  font-weight: 500;
}

.next-payment-cost s { color: #9a9aa0 !important; font-weight: 400; margin: 0 0.15em; }

.subscription-features-container .next-charge-time {
  margin-bottom: 0.5em;
  color: #69696e !important;
  font-size: 0.875em !important;
}

.cancel-save-offer-subscription-features {
  margin: 1em 0;
  text-align: left;
  display: inline-block;
}

.cancel-save-offer-subscription-features p,
.offer-mobile-description p {
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-size: 0.9375em;
  font-weight: normal;
  line-height: 1.6;
  color: #121416;
  padding: 0.25em 0;
}

.cancel-save-offer-subscription-features p:before,
.offer-mobile-description p:before {
  content: "\2713";
  font-weight: 700;
  color: #d72585 !important;
  margin-right: 0.75em;
}

.confirm-offer { justify-content: center; text-align: center; margin: 1.5em 0 0; }

/* Primary CTA — high specificity + !important to beat both the bundled CSS and tw-bg-primary */
.cancel-save-offer-container .confirm-offer button,
.cancel-save-offer-container .confirm-offer a {
  background: #d72585 !important;
  background-image: none !important;
  color: #ffffff !important;
  border: none !important;
  border-radius: 6px !important;
  padding: 14px 28px !important;
  font-size: 0.9375em !important;
  font-weight: 600 !important;
  cursor: pointer;
  transition: background-color 0.2s ease !important;
  text-decoration: none;
  display: inline-block;
}

.cancel-save-offer-container .confirm-offer button:hover,
.cancel-save-offer-container .confirm-offer a:hover {
  background: #b51d6f !important;
}

/* ----- Confirm dialog ----- */
.cancel-save-offer-container .offer-confirm-dialog-container {
  display: flex;
  position: fixed;
  width: 100%;
  height: 100%;
  background: rgba(18, 20, 22, 0.5);
  left: 0; top: 0;
  flex-direction: column;
  justify-content: center;
  z-index: 10;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog {
  display: flex;
  flex-direction: column;
  background: #ffffff;
  max-width: 750px;
  padding: 2em;
  margin: 0 auto;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
  border-radius: 12px;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-title {
  font-size: 1.5em; font-weight: 600; color: #121416;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-body-section {
  padding: 1em 0; color: #69696e; line-height: 1.5;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-body-section.offer {
  margin: 1em 0; padding: 1.5em; background: #f5f6f8; display: flex; border-radius: 8px;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-body-section.offer .offer-image {
  display: flex; padding: 1em;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-body-section.offer .offer-details {
  display: flex; flex-direction: column; justify-content: center;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-body-section.offer .offer-details .display-name {
  font-size: 1.1em; font-weight: 600; color: #121416;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-body-section.offer .offer-details .display-price {
  font-size: 0.9em; color: #d72585 !important; font-weight: 600;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-body-section.offer .offer-details .detailed-price {
  font-size: 0.75em; font-weight: 500; color: #69696e;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-body-section.offer img {
  width: 200px; border-radius: 4px;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-actions {
  display: flex; justify-content: flex-end; margin-top: 2em; gap: 0.75em;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-actions .confirm-action {
  padding: 12px 24px; border-radius: 6px; transition: all 0.2s ease;
  font-size: 0.875em; font-weight: 600; cursor: pointer;
  border: 1px solid #d72585 !important; color: #d72585 !important; background: transparent !important;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-actions .confirm-action:first-child {
  background: #d72585 !important; color: #ffffff !important; border-color: #d72585 !important;
}

.cancel-save-offer-container .offer-confirm-dialog-container .offer-confirm-dialog .confirm-actions .confirm-action:hover {
  opacity: 0.85;
}

.additional-buttons-container { display: flex; justify-content: center; margin-top: 1em; gap: 0.75em; }

.additional-buttons-container a,
.additional-buttons-container button {
  padding: 12px 24px; border-radius: 6px; font-size: 0.875em; font-weight: 600;
  cursor: pointer; transition: all 0.2s ease; text-decoration: none;
  border: 1px solid #d72585 !important; color: #d72585 !important; background: transparent !important;
}

.additional-buttons-container a:hover,
.additional-buttons-container button:hover {
  background: #d72585 !important; color: #ffffff !important;
}

.offer-mobile-description { display: none; }

@media (max-width: 600px) {
  .mobile-offer-header-wrapper { display: flex; justify-content: center; align-content: center; }
  .offer-mobile-description { display: flex; flex-direction: column; justify-content: center; }
  .cancel-save-offer-subscription-features { display: none; }
  .cancel-save-offer-heading { font-size: 1.75em; }
  .cancel-save-offer-body-container { padding: 2em 1.25em 1.5em !important; }
}
